\label{th:main1} The complex derivative of a length
coordinate with respect to a holomorphic coordinate equals half the integral of the corresponding harmonic Beltrami differential along the closed geodesic:
\begin{equation}\label{eq:main1}
\left.\frac{\partial \ell^i(s)}{\partial s^\kappa}\right|_{s_0}=
\frac{1}{2}\int_{\gamma_i} \mu_\kappa.
\end{equation}

\label{th:main2}
The tangent vector $\partial/\partial \tau^i|_{s_0}$ applied to a quadratic
holomorphic differential $\varphi=\varphi(z)dz^2$ is given by the integration
of the quadratic differential along the corresponding closed geodesic.
\begin{equation}\label{eq:main2}
\left(\left.\frac{\partial}{\partial \tau^i}\right|_{s_0}\!\!, \varphi(z)
dz^2\right)= \frac{\sqrt{-1}}{2} \int_{\gamma_i} \varphi.
\end{equation}

\label{cor:FNWP}
The Fen\-chel-Nielsen  symplectic form on the Teich\-mül\-ler  space is equal to the Weil-Pe\-ters\-son  form:
\begin{equation}\label{eq:FNWP}
\omega^{FN}=\omega^{WP} \text{, i.e. } -\sum_{i=1}^N d\tau^i\wedge d\ell^i =
\sqrt{-1}\; G_{\kappa{\overline{\lambda}}}^{WP}\; ds^\kappa\wedge ds^{\overline{\lambda}}.
\end{equation}

\label{cor:main1}
The vector fields $\partial/\partial \tau^j$ are Hamiltonian with respect to the Weil-Pe\-ters\-son  form:
\begin{eqnarray}
  \frac{\partial\ell^j}{\partial s^{\overline{\kappa}}}&=&-\sqrt{-1} \left\langle \frac{\partial}{\partial
  \tau^j}, \mu_\kappa\right\rangle, \label{eq:ltaudual1} \\
  \frac{\partial\ell^j}{\partial s^\kappa}&=& \sqrt{-1} \left\langle \mu_\kappa , \frac{\partial}{\partial
  \tau^j}\right\rangle. \label{eq:ltaudual2}
\end{eqnarray}

The length coordinates $\ell^j$ give rise to Hamiltonian vector fields
$\partial/\partial \ell^j$:
\begin{equation}\label{eq:detaues}
\frac{\partial \tau^j}{\partial s^\alpha}=-\sqrt{-1} \left\langle
\frac{\partial}{\partial s^\alpha},\frac{\partial}{\partial \ell^j}
\right\rangle.
\end{equation}

Let $\gamma$ and $\delta$ be closed geodesics on $X$. Then
\begin{equation}\label{eq:wol2.11}
\frac{\partial \ell(\gamma)}{\partial \tau(\delta)} = - \frac{\partial \ell(\delta)}{\partial\tau(\gamma)}.
\end{equation}

We show that the left-hand side is skew symmetric in $\gamma$ and $\delta$.

\begin{eqnarray*}
\frac{\partial \ell(\gamma)}{\partial \tau(\delta)} &=&2 \text{\rm Re}\left(
\frac{\partial\ell(\gamma)}{\partial s^\alpha}\cdot \frac{\partial s^\alpha}{\partial \tau(\delta)} \right)\\
&=\atop\eqref{eq:ltaudualvar}& 2 \text{\rm Re} \left(\sqrt{-1}\;\frac{\partial s^\alpha}{\partial \tau(\delta)}\cdot \left\langle\frac{\partial}{\partial s^\alpha},\frac{\partial}{\partial \tau(\gamma)}  \right\rangle \right)\\
&=& 2 \text{\rm Re} \left(\sqrt{-1}\;\frac{\partial s^\alpha}{\partial \tau(\delta)}\cdot\left\langle\frac{\partial}{\partial s^\alpha},\frac{\partial s^\beta}{\partial\tau(\gamma)}\frac{\partial}{\partial s^\beta} \right\rangle \right) \text{\footnotesize\quad (type consideration) }\\
&=& 2 \text{\rm Re} \left( \sqrt{-1}\; G^{WP}_{\alpha{\overline{\beta}}}\frac{\partial s^\alpha}{\partial\tau(\delta)} \frac{\partial s^{\overline{\beta}}}{\partial \tau(\gamma)} \right)\\
&=& \sqrt{-1} \; G^{WP}_{\alpha{\overline{\beta}}} \left(\frac{\partial s^\alpha}{\partial \tau(\delta)}
\frac{\partial s^{\overline{\beta}}}{\partial \tau(\gamma)} - \frac{\partial s^\alpha}{\partial \tau(\gamma)}
\frac{\partial s^{\overline{\beta}}}{\partial \tau(\delta)}\right).
\end{eqnarray*}
